-- 쓰레드 정보 최초는 '' 이고 top 10개 조회후에 쓰레드 명 넣고 이 리스트 가지고 처리 한다.
CREATE TABLE exps.dbo.TB_EDI_GOV_RECV_BMS (
      EDI_SEQ_NO int IDENTITY(1,1) NOT NULL,
      ENT_CODE varchar(5) COLLATE Korean_Wansung_CI_AS NOT NULL,
      TYPE_CODE varchar(9) COLLATE Korean_Wansung_CI_AS NULL,
      RECV_STATUS varchar(1) COLLATE Korean_Wansung_CI_AS DEFAULT 'N' NULL,
      EDI_DESC varbinary(MAX) NULL,
      RECV_DATE_TIME datetime DEFAULT getdate() NULL,
      CUS_SEND_TYPE varchar(5) COLLATE Korean_Wansung_CI_AS DEFAULT 'REST' NULL,
      THREAD_NAME varchar(30) COLLATE Korean_Wansung_CI_AS DEFAULT '' NULL,
      CONSTRAINT PK_TB_EDI_GOV_RECV_BMS PRIMARY KEY (EDI_SEQ_NO)
);

