UPDATE TB_EDI_GOV_RECV_BMS
SET THREAD_NAME = '2'
  , RECV_STATUS ='P'
FROM ( SELECT TOP 5 *
       FROM TB_EDI_GOV_RECV_BMS
       WHERE (1=1)
         AND TYPE_CODE   = 'GOVCBR5IJ'
       ORDER BY EDI_SEQ_NO
         -- 여기에 필요한 조건 등을 추가할 수 있습니다.
     ) AS TU
;


