UPDATE TB_EDI_GOV_RECV_BMS
SET THREAD_NAME = '2'
  , RECV_STATUS ='P'
WHERE EDI_SEQ_NO IN (
    SELECT
        TOP 2
        EDI_SEQ_NO
    FROM TB_EDI_GOV_RECV_BMS
    WHERE TYPE_CODE = 'GOVCBR5IJ'
      AND RECV_STATUS NOT IN ('E', 'P')
    ORDER BY EDI_SEQ_NO
)
;




SELECT
    EDI_SEQ_NO
     , ENT_CODE
     , TYPE_CODE
     , CASE CUS_SEND_TYPE
           WHEN 'DB' THEN CONVERT(VARCHAR(MAX), EDI_DESC)
           ELSE CONVERT(NVARCHAR(MAX), EDI_DESC) END AS EDI_DESC
     , RECV_DATE_TIME
     , CONVERT(VARCHAR(10), RECV_DATE_TIME, 23)      AS RECV_DATE
     , CONVERT(VARCHAR(10), RECV_DATE_TIME, 108)     AS RECV_TIME
FROM TB_EDI_GOV_RECV_BMS
WHERE (1 = 1)
  AND TYPE_CODE   = 'GOVCBR5IJ'
  AND THREAD_NAME =  'Bms_Recv_GOVCBR5IJ_1'
  AND RECV_STATUS NOT IN ('E' , 'P')


